            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return out

    top, bottom = bands
    # A positive shift means the lower copy is shifted right relative to the upper.
    best_shift, best_score = 0, None
    for shift in range(-4, 5):
        score = 0
        for ra, rb in zip(top, bottom):
            for ca in range(w):
                cb = ca + shift
                va = grid[ra][ca] if 0 <= ca < w else bg
                vb = grid[rb][cb] if 0 <= cb < w else bg
                # Foreground agreement is informative; ignore background/background.
                fa, fb = va != bg, vb != bg
                if fa or fb:
                    score += 2 if fa and fb and va == vb else -2
        if best_score is None or score > best_score:
            best_shift, best_score = shift, score

    shift = best_shift
    for ra, rb in zip(top, bottom):
        if shift > 0:
            # Copy differences from the upper pattern into the right-shifted lower copy.
            for ca in range(w):
                cb = ca + shift
                if cb >= w:
