                if ca >= w:
                    continue
                if grid[rb][cb] != grid[ra][ca]:
                    out[ra][ca] = 1
        else:
            # With no displacement, mark the differing cells on the upper copy.
            for c in range(w):
                if grid[ra][c] != grid[rb][c]:
                    out[ra][c] = 1
    return out
